      question: 'PM описывает целевой сегмент EdTech как «студенты 18-25, желающие выучить английский». Что улучшит эту сегментацию?',
      options: ['Добавить возрастные диапазоны', 'Добавить географию', 'Уточнить JTBD и контекст использования', 'Уточнить уровень дохода'],
